{
  "name": "opencode-deepseek-search-fetch",
  "version": "1.2.0",
  "description": "DeepSeek Search & Fetch API for OpenCode V2: native websearch provider plus webfetch integration with smart fallback",
  "type": "module",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src"
  ],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "lint": "biome check .",
    "check": "bun run typecheck && bun run lint && bun test"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "deepseek",
    "websearch",
    "webfetch"
  ],
  "license": "AGPL-3.0-only",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Cle2ment/opencode-deepseek-search-fetch.git"
  },
  "bugs": {
    "url": "https://github.com/Cle2ment/opencode-deepseek-search-fetch/issues"
  },
  "homepage": "https://github.com/Cle2ment/opencode-deepseek-search-fetch#readme",
  "dependencies": {
    "@opencode/plugin": "^2.2.0"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.3.0",
    "@types/bun": "^1.3.0",
    "typescript": "^5.9.0"
  }
}
